from pathlib import Path
import base64, gzip

DATA = {'1401': '', '1402': '', '1403': '', '1404': ''}

root = Path(__file__).resolve().parents[1]
for year, payload in DATA.items():
    out = root / 'data' / 'capacity' / 'normalized' / year / 'capacities-maternity-emergency.csv'
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_bytes(gzip.decompress(base64.b64decode(payload)))
    print(f'wrote {out}')
